// 1. Extract raw job details and citation URLs
const rawItem = items[0].json;

let jobDetails = {};
try {
    jobDetails = JSON.parse(rawItem.content.parts[0].text);
} catch (error) {
    throw new Error("Invalid JSON in content.parts[0].text");
}

// 2. Extract citation URLs and remove duplicates (safe if missing)
const urls = rawItem.citationMetadata && rawItem.citationMetadata.citationSources
    ? rawItem.citationMetadata.citationSources
        .map(c => c.uri)
        .filter((value, index, self) => self.indexOf(value) === index) // deduplicate
    : [jobDetails["Job apply URL"]]; // fallback to jobDetails link if no citationMetadata

// 3. Define standard keys
const keys = [
  "Job title",
  "company name",
  "job location",
  "applicant count",
  "post data",
  "post time",
  "recrutier contact information",
  "location type",
  "job type",
  "Application way",
  "skills",
  "Job description",
  "Benefits",
  "Location",
  "Job apply URL"
];

// 4. Create polished array (one entry per unique URL)
const polishedJobs = urls.map(url => {
    const polished = {};
    keys.forEach(key => {
        if (key === "Job apply URL") {
            polished[key] = url;
        } else {
            polished[key] = jobDetails[key] || "";
        }
    });
    return polished;
});

// 5. Return directly as array of objects
return polishedJobs.map(job => ({ json: job }));

